mapper.select:
SELECT w.id, w.name, w.namespace, w.create_time, w.status, w.annotations, w.labels, w.spec, w.status_more, w.username, w.info_json, w.add_row_time, w.foreign_key, w.change_time, w.cluster FROM workflow w LEFT JOIN project p ON w.namespace = p.name WHERE 1=1
AND p.name = #{namespace}
AND w.status = #{status}
AND w.labels LIKE CONCAT('%', #{label}, '%')
AND w.name LIKE CONCAT('%', #{name}, '%')
AND w.username LIKE CONCAT('%', #{username}, '%')
ORDER BY w.add_row_time DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM workflow w LEFT JOIN project p ON w.namespace = p.name WHERE 1=1
AND p.name = #{namespace}
AND w.status = #{status}
AND w.labels LIKE CONCAT('%', #{label}, '%')
AND w.name LIKE CONCAT('%', #{name}, '%')
AND w.username LIKE CONCAT('%', #{username}, '%')
